---
// Private, local-only site-graph explorer.
//
// This file lives OUTSIDE src/pages/ on purpose: it only becomes a route via the
// dev-only `injectRoute` in astro.config.mjs, which runs only under `astro dev`.
// It is never part of a production build, so it stays off the public site.
//
// Visit http://localhost:4321/graph while running `npm run dev`.
import { Graph } from 'starlight-site-graph/components';
import config from 'virtual:starlight-site-graph/config';

// In dev the integration inlines the generated sitemap into the virtual config.
const sitemap = config.sitemapConfig?.sitemap ?? {};
const nodeCount = Object.keys(sitemap).length;

// The inline widget is page-centric; seed it with a real node so it is not empty,
// then use the fullscreen action for the whole-site view.
const seedSlug = Object.keys(sitemap)[0] ?? '/';

const graphConfig = {
  ...config.graphConfig,
  depth: 6,
  actions: ['fullscreen', 'depth', 'reset-zoom', 'render-arrows', 'render-unresolved', 'settings'],
  enableZoom: true,
  enableDrag: true,
  enablePan: true,
};
---

<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta name="robots" content="noindex, nofollow" />
    <title>Site graph (dev only)</title>
    <style>
      html,
      body {
        margin: 0;
        height: 100%;
        background: #0e1116;
        color: #e6e6e6;
        font-family: system-ui, sans-serif;
      }
      .toolbar {
        padding: 0.5rem 1rem;
        font-size: 0.85rem;
        border-bottom: 1px solid #2a2f3a;
      }
      .graph-wrap {
        height: calc(100vh - 2.5rem);
      }
      /* The graph fills its container. */
      .graph-wrap :global(.slsg-graph-component) {
        height: 100%;
      }
    </style>
  </head>
  <body>
    <div class="toolbar">
      Site graph (dev only) · {nodeCount} nodes · click the fullscreen action for the whole-site view
    </div>
    <div class="graph-wrap">
      <Graph slug={seedSlug} sitemap={sitemap} config={graphConfig} />
    </div>
  </body>
</html>

