// @ts-check
import { defineConfig } from 'astro/config';

import react from '@astrojs/react';
import icon from 'astro-icon';
import mdx from '@astrojs/mdx';
import tailwindcss from '@tailwindcss/vite';

import { unified } from '@astrojs/markdown-remark';
import remarkExternalLinks from './src/utils/plugins/remarkExternalLinks';
import remarkGfm from 'remark-gfm';
import rehypeFootnoteLinks from './src/utils/plugins/rehypeFootnoteLinks';

import sitemap from '@astrojs/sitemap';
import netlify from '@astrojs/netlify';

import { redirects } from './src/constants/redirects';

import siteGraph from 'starlight-site-graph/integration';

// The site-graph explorer is a private, local-only tool. It is wired up ONLY
// under `astro dev`, so neither the graph route nor the generated sitemap data
// is ever emitted into a production build. In dev, starlight-site-graph inlines
// the sitemap straight into the page (it only fetches /sitegraph/sitemap.json in
// PROD), so gating on the dev command keeps the whole feature off the public site.
const isDev = process.argv.includes('dev');

// Injects the /graph route from src/dev/ (outside src/pages/, so it never becomes
// a route on its own). Added only when isDev, so it cannot leak into production.
const devGraphRoute = {
  name: 'apr-dev-graph-route',
  hooks: {
    'astro:config:setup': ({ injectRoute }) => {
      injectRoute({
        pattern: '/graph',
        entrypoint: './src/dev/site-graph.astro',
        prerender: true,
      });
    },
  },
};

const devGraphIntegrations = isDev
  ? [
      siteGraph({
        // Build the graph from blog + glossary MDX, whose file paths map cleanly
        // to /blog/<slug>/ and /glossary/<slug>/ URLs (unlike src/content/pages,
        // which route at the site root and would not match).
        sitemapConfig: {
          // Relative to the project root: the builder runs trimSlashes() on this
          // and walks it from cwd, so an absolute path would break.
          contentRoot: 'src/content',
          pageInclusionRules: ['/blog/**', '/glossary/**', '!**/*'],
        },
      }),
      devGraphRoute,
    ]
  : [];

export default defineConfig({
  site: 'https://agilepainrelief.com',
  output: 'static',
  integrations: [react(), icon(), mdx(), sitemap(), ...devGraphIntegrations],

  markdown: {
    processor: unified({
      remarkPlugins: [remarkExternalLinks, remarkGfm],
      rehypePlugins: [rehypeFootnoteLinks],
    }),
  },

  adapter: netlify({ imageCDN: false }),

  vite: {
    plugins: [tailwindcss()],
  },

  experimental: {
    contentIntellisense: true,
  },

  redirects,
});

