toolUseResult.originalFile:
// Builds the graph sitemap for the dev-only /graph explorer.
//
// We generate it ourselves instead of letting starlight-site-graph@0.5.0 scan the
// content, because that version has two standalone bugs: it hardcodes contentRoot
// to ./src/pages, and its naive markdown-link regex throws on real MDX (URLs with
// parentheses), aborting the whole integration. Passing a ready-made sitemap via
// `sitemapConfig.sitemap` makes the integration skip its scanner entirely.
//
// Node keys and links use the plugin's "simplified" slug form (no leading slash,
// trailing slash kept, e.g. `blog/foo/`): the client keys nodes with simplifySlug
// but matches link targets raw, so both sides must already be in that form.
import fs from 'node:fs/promises';
import path from 'node:path';

// Astro bundles astro.config and its local imports, so import.meta.url points at a
// temp path there; resolve from the project root (cwd under `astro dev`) instead.
const CONTENT = path.join(process.cwd(), 'src', 'content');
const COLLECTIONS = ['blog', 'glossary'];

/** `blog/some-slug/` — matches the plugin's simplifySlug output for /blog/some-slug/. */
const nodeKey = (collection, slug) => `${collection}/${slug}/`;

/** Pull a scalar frontmatter field out of a YAML block with a forgiving regex. */
function frontmatterField(fm, field) {
  const m = fm.match(new RegExp(`^${field}:\\s*(.+)$`, 'm'));
  if (!m) return undefined;
  return m[1].trim().replace(/^['"]|['"]$/g, '');
}

/** Parse a simple inline YAML list: `relatedTerms: ['a', 'b']`. */
function frontmatterList(fm, field) {
  const m = fm.match(new RegExp(`^${field}:\\s*\\[(.*?)\\]`, 'm'));
  if (!m) return [];
  return m[1]
    .split(',')
    .map((s) => s.trim().replace(/^['"]|['"]$/g, ''))
    .filter(Boolean);
}

export async function buildDevSitemap() {
  /** @type {Record<string, {external: boolean, exists: boolean, title: string, links: string[]}>} */
  const sitemap = {};
  /** @type {Array<{key: string, body: string, related: string[]}>} */
  const pages = [];

  for (const collection of COLLECTIONS) {
    const dir = path.join(CONTENT, collection);
    let entries;
    try {
      entries = await fs.readdir(dir, { withFileTypes: true });
    } catch {
      continue; // collection folder absent
    }

    for (const entry of entries) {
      if (!entry.isDirectory()) continue;
      const slug = entry.name;
      const file = path.join(dir, slug, 'index.mdx');
      let raw;
      try {
        raw = await fs.readFile(file, 'utf8');
      } catch {
        continue; // no index.mdx (e.g. stray folder)
      }

      const fmMatch = raw.match(/^---\n([\s\S]*?)\n---/);
      const fm = fmMatch ? fmMatch[1] : '';
      const body = fmMatch ? raw.slice(fmMatch[0].length) : raw;

      if (frontmatterField(fm, 'draft') === 'true') continue;

      const key = nodeKey(collection, slug);
      sitemap[key] = {
        external: false,
        exists: true,
        title: frontmatterField(fm, 'title') ?? slug,
        links: [],
      };

      // relatedTerms are bare glossary slugs; treat them as glossary edges.
      const related =
        collection === 'glossary'
          ? frontmatterList(fm, 'relatedTerms').map((s) => nodeKey('glossary', s))
          : [];

      pages.push({ key, body, related });
    }
  }

  const known = new Set(Object.keys(sitemap));
  const linkPattern = /\/(blog|glossary)\/([a-z0-9][a-z0-9-]*)\/?/g;

  for (const { key, body, related } of pages) {
    const targets = new Set(related);
    for (const match of body.matchAll(linkPattern)) {
      targets.add(nodeKey(match[1], match[2]));
    }
    sitemap[key].links = [...targets].filter((t) => t !== key && known.has(t));
  }

  return sitemap;
}

