toolUseResult.originalFile:
// Builds the graph sitemap for the dev-only /graph explorer.
//
// We generate it ourselves instead of letting starlight-site-graph@0.5.0 scan the
// content, because that version has two standalone bugs: it hardcodes contentRoot
// to ./src/pages, and its naive markdown-link regex throws on real MDX (URLs with
// parentheses), aborting the whole integration. Passing a ready-made sitemap via
// `sitemapConfig.sitemap` makes the integration skip its scanner entirely.
//
// Node keys and links use the plugin's "simplified" slug form (no leading slash,
// trailing slash kept, e.g. `blog/foo/`): the client keys nodes with simplifySlug
// but matches link targets raw, so both sides must already be in that form.
import fs from 'node:fs/promises';
import path from 'node:path';

// Astro bundles astro.config and its local imports, so import.meta.url points at a
// temp path there; resolve from the project root (cwd under `astro dev`) instead.
const CONTENT = path.join(process.cwd(), 'src', 'content');
const COLLECTIONS = ['blog', 'glossary'];

/** `blog/some-slug/` — matches the plugin's simplifySlug output for /blog/some-slug/. */
const nodeKey = (collection, slug) => `${collection}/${slug}/`;

/** Pull a scalar frontmatter field out of a YAML block with a forgiving regex. */
function frontmatterField(fm, field) {
  const m = fm.match(new RegExp(`^${field}:\\s*(.+)$`, 'm'));
  if (!m) return undefined;
  return m[1].trim().replace(/^['"]|['"]$/g, '');
}

/** Parse a simple inline YAML list: `relatedTerms: ['a', 'b']`. */
function frontmatterList(fm, field) {
  const m = fm.match(new RegExp(`^${field}:\\s*\\[(.*?)\\]`, 'm'));
  if (!m) return [];
  return m[1]
    .split(',')
    .map((s) => s.trim().replace(/^['"]|['"]$/g, ''))
    .filter(Boolean);
}

export async function buildDevSitemap() {
  /** @type {Record<string, {external: boolean, exists: boolean, title: string, links: string[], backlinks: string[]}>} */
  const sitemap = {};
  /** @type {Array<{key: string, body: string, related: string[]}>} */
  const pages = [];

  for (const collection of COLLECTIONS) {
    const dir = path.join(CONTENT, collection);
    let entries;
    try {
      entries = await fs.readdir(dir, { withFileTypes: true });
    } catch {
      continue; // collection folder absent
    }

    for (const entry of entries) {
      if (!entry.isDirectory()) continue;
      const slug = entry.name;
      const file = path.join(dir, slug, 'index.mdx');
      let raw;
      try {
        raw = await fs.readFile(file, 'utf8');
      } catch {
        continue; // no index.mdx (e.g. stray folder)
      }

      const fmMatch = raw.match(/^---\n([\s\S]*?)\n---/);
      const fm = fmMatch ? fmMatch[1] : '';
      const body = fmMatch ? raw.slice(fmMatch[0].length) : raw;

      if (frontmatterField(fm, 'draft') === 'true') continue;

      const key = nodeKey(collection, slug);
      sitemap[key] = {
        external: false,
        exists: true,
        title: frontmatterField(fm, 'title') ?? slug,
        links: [],
        backlinks: [],
      };

      // relatedTerms are bare glossary slugs; treat them as glossary edges.
      const related =
        collection === 'glossary'
          ? frontmatterList(fm, 'relatedTerms').map((s) => nodeKey('glossary', s))
          : [];

      pages.push({ key, body, related });
    }
  }

  const known = new Set(Object.keys(sitemap));
  const linkPattern = /\/(blog|glossary)\/([a-z0-9][a-z0-9-]*)\/?/g;

  for (const { key, body, related } of pages) {
    const targets = new Set(related);
    for (const match of body.matchAll(linkPattern)) {
      targets.add(nodeKey(match[1], match[2]));
    }
    sitemap[key].links = [...targets].filter((t) => t !== key && known.has(t));
  }

  // Backlinks (reverse edges). The graph's depth traversal walks both directions,
  // so without these a page reached only via incoming links looks orphaned.
  for (const key of known) sitemap[key].backlinks = [];
  for (const key of known) {
    for (const target of sitemap[key].links) sitemap[target].backlinks.push(key);
  }

  return sitemap;
}

---
// Private, local-only site-graph explorer.
//
// This file lives OUTSIDE src/pages/ on purpose: it only becomes a route via the
// dev-only `injectRoute` in astro.config.mjs, which runs only under `astro dev`.
// It is never part of a production build, so it stays off the public site.
//
// Visit http://localhost:4321/graph while running `npm run dev`.
//
// The graph data is built here (not by the starlight-site-graph integration, whose
// 0.5.0 standalone data path is broken for our content: see build-sitemap.mjs). We
// still read graphConfig from the integration's virtual module for its complete,
// schema-defaulted settings, then render the plugin's <Graph> with our own sitemap.
import { Graph } from 'starlight-site-graph/components';
import config from 'virtual:starlight-site-graph/config';
import 'starlight-site-graph/styles/variables.css';
import { buildDevSitemap } from './build-sitemap.mjs';

const sitemap = await buildDevSitemap();
const nodeCount = Object.keys(sitemap).length;
const edgeCount = Object.values(sitemap).reduce(
  (n, e) => n + (e.links?.length ?? 0),
  0
);

// The graph renders the neighbourhood of a centre page out to `depth` (depth >= 5
// renders the whole site at once, which is an unreadable hairball at this scale).
// So default to a readable LOCAL view centred on the most-connected page, and let
// the URL override both: /graph?page=blog/some-slug/&depth=3
const degree = (k) =>
  (sitemap[k].links?.length ?? 0) + (sitemap[k].backlinks?.length ?? 0);
const mostConnected =
  Object.keys(sitemap).sort((a, b) => degree(b) - degree(a))[0] ?? '/';

const params = Astro.url.searchParams;
const seedSlug = params.get('page') || mostConnected;
const rawDepth = Number.parseInt(params.get('depth') ?? '', 10);
const depth = Number.isFinite(rawDepth) ? Math.max(1, Math.min(rawDepth, 6)) : 2;

// Keep the plugin's default actions (they already include fullscreen + a depth
// stepper). The whole-site view is the fullscreen action or ?depth=5.
const graphConfig = {
  ...config.graphConfig,
  depth,
  depthDirection: 'both',
  enableZoom: true,
  enableDrag: true,
  enablePan: true,
};
---

<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    {
      /* micromatch (pulled in by the graph client) references Node's `process`
        global, which does not exist in the browser. Shim it before any module
        script runs. Dev-only page, so this never ships to production. */
    }
    <script is:inline>
      window.process = window.process || {
        env: {},
        platform: '',
        argv: [],
        cwd: () => '/',
      };
    </script>
    <meta name="robots" content="noindex, nofollow" />
    <title>Site graph (dev only)</title>
    <style>
      html,
      body {
        margin: 0;
        height: 100%;
        background: #0e1116;
        color: #e6e6e6;
        font-family: system-ui, sans-serif;
      }
      .toolbar {
        padding: 0.5rem 1rem;
        font-size: 0.85rem;
        border-bottom: 1px solid #2a2f3a;
      }
      .graph-wrap {
        height: calc(100vh - 2.5rem);
        /* The plugin sizes the graph off these vars (default ~15vw sidebar size);
           override so it fills the whole page. */
        --slsg-graph-width: 100%;
        --slsg-graph-height: 100%;
      }
      .graph-wrap :global(.slsg-graph-component),
      .graph-wrap :global(.slsg-graph-container) {
        width: 100%;
        height: 100%;
      }
    </style>
  </head>
  <body>
    <div class="toolbar">
      Site graph (dev only) · {nodeCount} nodes · {edgeCount} links · centred on <code>{seedSlug}</code> at depth {depth} · re-centre with <code>?page=blog/some-slug/</code>, change spread with <code>?depth=1-6</code> (5+ = whole site)
    </div>
    <div class="graph-wrap">
      <Graph slug={seedSlug} sitemap={sitemap} config={graphConfig} />
    </div>
  </body>
</html>

